VALUES ('sap', '¿Qué consecuencia inmediata tiene desactivar un artículo en la tabla WLK1 para un centro?', 'Convierte el artículo en un activo intangible de amortización acelerada.', 'Borra físicamente todos los registros contables históricos de la empresa.', 'Desconecta los servidores de la tienda de la red corporativa central.', 'Impide compras, recepciones y bloquea la venta del artículo en ese centro.', 'D', 'Senior', 'Al cerrarse el listado en WLK1, las funciones de compras y ventas quedan inhabilitadas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En S/4HANA Retail, ¿qué técnica previene bloqueos de tablas en facturación masiva?', 'Desacoplamiento de contabilización y procesamiento en paralelo de entregas.', 'Uso de un único usuario genérico que procese todas las órdenes secuencialmente.', 'Eliminación permanente de las llaves primarias en tablas de documentos.', 'Desactivación de los registros de auditoría y controles fiscales del sistema.', 'A', 'Senior', 'Procesa paquetes asíncronos distribuidos en memoria reduciendo bloqueos en ACDOCA/VBRK.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Cómo optimiza SAP Retail la valoración de inventarios por el método Retail (RVM)?', 'Calcula el costo sumando manualmente las notas de remisión de proveedores.', 'Valora el stock total a precio de venta aplicando márgenes por categoría.', 'Establece un precio fijo inmutable durante diez años para todo el inventario.', 'Reemplaza la valoración en dinero por conteo de volumen cúbico de almacén.', 'B', 'Senior', 'RVM permite estimar el costo de stocks masivos cuando no es viable rastrear costo unitario.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En integración POS-ERP, ¿cuál es la diferencia clave entre IDocs WPUUMS y WPUBON?', 'WPUUMS se utiliza en banca; WPUBON se utiliza en manufactura pesada.', 'WPUUMS solo procesa devoluciones; WPUBON solo procesa cobros en efectivo.', 'WPUUMS envía ventas agregadas por artículo; WPUBON envía detalle por ticket.', 'WPUUMS no genera asientos contables; WPUBON solo genera archivos de texto.', 'C', 'Senior', 'WPUUMS reduce el volumen de documentos en FI/MM; WPUBON mantiene trazabilidad unitaria.', 1);
