VALUES ('sap', 'En UDF, ¿qué es un Factor de Influencia de la Demanda (DIF)?', 'Un error en el disco duro que daña las series de tiempo almacenadas.', 'Variable como promociones, precios o festividades que altera el patrón de compra.', 'Un indicador financiero de solvencia que emite el banco central del país.', 'Una clave de acceso cifrada para ingresar al panel de administración técnica.', 'B', 'Semi-Senior', 'Los DIFs permiten al modelo matemático aislar y predecir el impacto de promociones y clima.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Cómo gestiona UDF los desabastos (quiebres de stock) al modelar la demanda?', 'Crea pedidos de compra automáticos sin validar presupuesto disponible.', 'Asume que los clientes perdieron interés y reduce el pronóstico a cero.', 'Estima las ventas perdidas (Lost Sales) para no subestimar la demanda futura.', 'Borra del catálogo el artículo que se quedó sin existencias físicas.', 'C', 'Semi-Senior', 'Si hubo desabasto, la venta fue cero pero la demanda real no; UDF corrige esa distorsión.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Qué función cumple el Rough Stock Indicator (RSI) en SAP OAA?', 'Asigna códigos de barras provisionales a productos sin empaque original.', 'Calcula el peso total de la mercancía para contratar camiones de carga.', 'Determina la depreciación contable de estanterías en tiendas físicas.', 'Genera semáforos de disponibilidad para catálogos web de alta concurrencia.', 'D', 'Semi-Senior', 'El RSI clasifica el stock en verde, amarillo y rojo para responder a millones de hits web.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En POS DTA, ¿qué tabla almacena el registro transaccional plano de ventas?', '/POSDW/TLOGF.', 'BSIS.', 'COEP.', 'CDHDR.', 'A', 'Semi-Senior', '/POSDW/TLOGF guarda el Transaction Log en formato aplanado para alta velocidad de ingesta.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Qué BAdI en POS DTA permite transformar y enriquecer datos en la ingesta?', 'BADI_MATERIAL_CHECK.', '/POSDW/BADI_RFINS.', 'BADI_ACC_DOCUMENT.', 'BADI_CUSTOMER_ADD_DATA.', 'B', 'Semi-Senior', '/POSDW/BADI_RFINS intercepta la transacción cruda de POS antes de grabarla en el log de CAR.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En OPP, ¿qué estándar de la industria minorista modela las reglas de promoción?', 'Protocolo IEEE 802.11 de comunicaciones.', 'Norma ISO 9001 de gestión de calidad.', 'Estándar OASIS ARTS (Association for Retail Technology Standards).', 'Estándar ANSI C de compilación de código.', 'C', 'Semi-Senior', 'ARTS define la estructura XML/JSON unificada para promociones complejas en retail.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Cómo evita OAA que dos compradores web adquieran la última unidad disponible?', 'Cancelando ambos pedidos y emitiendo notas de crédito compensatorias.', 'Bloqueando el acceso a la tienda online a usuarios de ciertas regiones.', 'Obligando a los clientes a pagar exclusivamente con depósito en efectivo.', 'Creando reservas temporales (Temporary Reservations) durante el checkout.', 'D', 'Semi-Senior', 'Las reservas temporales congelan el stock por unos minutos mientras se procesa el pago.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Qué biblioteca matemática de SAP HANA ejecuta los algoritmos de UDF?', 'SAP HANA PAL (Predictive Analysis Library).', 'jQuery UI Framework.', 'Apache Lucene Engine.', 'Node.js Express Module.', 'A', 'Semi-Senior', 'PAL corre de manera nativa en el motor C++ de HANA para cálculos estadísticos en paralelo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En POS DTA, ¿qué inconsistencia detecta la tarea \"Gap Check\"?', 'Diferencias en los precios de compra pactados con proveedores extranjeros.', 'Saltos o números faltantes en la secuencia consecutiva de tickets de una caja.', 'Falta de sellos fiscales en documentos de importación de aduanas.', 'Retrasos en la entrega de uniformes al personal de seguridad de tiendas.', 'B', 'Semi-Senior', 'El Gap Check alerta si se omitió un ticket entre dos transacciones correlativas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Cómo opera el Promotion Pricing Service (PPS) en modo embebido en la caja registradora?', 'Apaga la pantalla de la caja si la transacción supera cierto monto fijado.', 'Transmite cada clic del mouse al centro de cómputo corporativo central.', 'Calcula promociones localmente en caja incluso sin conexión a internet.', 'Imprime cupones de lotería estatal al finalizar cada cobro en efectivo.', 'C', 'Semi-Senior', 'El motor PPS local consume las promociones sincronizadas previamente para operar offline.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En SAP CAR, ¿qué información almacena Multichannel Sales Repository (MCSR)?', 'Los contratos de arrendamiento de locales comerciales de la cadena.', 'Los curriculum vitae de los candidatos a puestos de cajeros en tienda.', 'Las grabaciones de video del circuito cerrado de vigilancia de tiendas.', 'Todas las transacciones de venta sin importar si fueron físicas o en línea.', 'D', 'Semi-Senior', 'MCSR es el almacén central de ventas unificadas para analítica omnicanal en tiempo real.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Qué tipo de promoción OPP otorga beneficio al comprar artículos combinados?', 'Promoción tipo Mix and Match.', 'Descuento por método de pago bancario.', 'Aumento de precio por horario pico.', 'Cobro de comisión por empaque biodegradable.', 'A', 'Semi-Senior', 'Mix and Match permite combinar productos de distintas líneas con descuento unificado.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Qué IDoc de salida de POS DTA contabiliza cobros y medios de pago en FI?', 'ORDERS05.', 'WPUTAB.', 'DELVRY03.', 'CREMAS01.', 'B', 'Semi-Senior', 'WPUTAB transfiere los desgloses de tarjetas, efectivo y vales a las cuentas contables de FI.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En Demand Data Foundation (DDF), ¿qué modela la entidad \"Offer\"?', 'Solicitudes de contratación de nuevo personal administrativo.', 'Presupuestos de gastos de viaje de ejecutivos comerciales.', 'Promociones comerciales con vigencia, condiciones de precio y productos.', 'Listados de refacciones para camiones de distribución regional.', 'C', 'Semi-Senior', 'La entidad Offer estructura las campañas promocionales que consumen UDF y OPP.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En eventos masivos como Black Friday, ¿cómo se optimiza la ingesta en POS DTA?', 'Ejecución de auditorías síncronas bloqueando la caja en cada venta.', 'Pausa total de la base de datos hasta que termine la venta en tiendas.', 'Eliminación del cálculo de impuestos en todas las cajas registradoras.', 'Ingesta masiva en /POSDW/TLOGF desacoplada de tareas de auditoría en batch.', 'D', 'Senior', 'Separar la recepción plana (/POSDW/TLOGF) del procesamiento analítico evita cuellos de botella.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Cómo determina OAA el nodo óptimo de despacho para pedidos e-commerce?', 'Aplica estrategias de sourcing basadas en proximidad, stock libre y costo.', 'Envía siempre el pedido al centro de distribución más lejano del cliente.', 'Obliga al cliente a recoger la mercancía en oficinas corporativas centrales.', 'Asigna el pedido a la tienda que tenga menos empleados contratados.', 'A', 'Senior', 'OAA optimiza si despachar desde tienda cercana (Ship-from-Store) o desde almacén central.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En UDF, ¿cuál es la diferencia conceptual entre Demand Estimating y Forecasting?', 'Estimating solo calcula compras; Forecasting solo calcula devoluciones de clientes.', 'Estimating pondera factores pasados; Forecasting proyecta la demanda futura.', 'Estimating se ejecuta en el ERP; Forecasting se ejecuta en hojas de cálculo.', 'Estimating borra registros históricos; Forecasting genera facturas fiscales.', 'B', 'Senior', 'La estimación calibra el modelo con ventas históricas; el pronóstico predice ventas futuras.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Qué regla aplica OPP cuando dos promociones no combinables aplican a un artículo?', 'Cancela la venta y expulsa al usuario del portal de compras web.', 'Suma ambos descuentos superando el valor original del producto.', 'Regla de Mejor Precio (Best Price) aplicando el mayor ahorro al cliente.', 'Aplica el precio más caro ignorando los descuentos configurados.', 'C', 'Senior', 'OPP resuelve conflictos seleccionando la promoción que otorga mayor beneficio al cliente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Cómo se concilia el inventario vendido en CAR contra el stock de SAP ERP?', 'Suponiendo que el inventario en tienda no varía con las ventas de caja.', 'Restando las ventas de CAR únicamente a fin de año en un asiento manual.', 'Contando físicamente todos los artículos de las tiendas cada cuatro horas.', 'Comparando los movimientos de salida agregados de CAR contra los PGIs en ERP.', 'D', 'Senior', 'La auditoría de interfaces coteja que cada ticket de CAR tenga su reflejo contable en ERP.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En SAP CAR, ¿qué rol técnico juegan las vistas CDS Virtual Data Model (VDM)?', 'Proveer capas semánticas de reporting en tiempo real sin duplicar datos en tablas.', 'Generar scripts de respaldo en cinta magnética fuera de las instalaciones.', 'Bloquear el acceso de usuarios con contraseñas que tengan números repetidos.', 'Crear interfaces gráficas para terminales móviles con pantallas monocromáticas.', 'A', 'Senior', 'Las vistas VDM leen los datos transaccionales en memoria ofreciendo KPIs instantáneos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Qué debe ocurrir en POS DTA si se recibe un Post-Void de un ticket ya enviado a ERP?', 'Ignorar la anulación y dejar que el cliente asuma el cargo duplicado.', 'Ejecutar una tarea de compensación o reversa en el ERP para anular el impacto.', 'Borrar el ticket de la base de datos de CAR sin notificar a contabilidad.', 'Bloquear la terminal de cobro hasta que un auditor visite la sucursal.', 'B', 'Senior', 'El Post-Void debe generar el movimiento inverso en ERP para mantener la consistencia contable.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Cómo emplea el módulo On-Shelf Availability (OSA) el análisis de patrones?', 'Mide la velocidad del viento en el estacionamiento para evitar accidentes.', 'Reconoce rostros de compradores habituales para ofrecerles cupones en caja.', 'Identifica pausas anómalas en ventas de alta rotación para alertar góndolas vacías.', 'Detecta si los cajeros ingresaron productos con las dos manos o con una.', 'C', 'Senior', 'Si un artículo que se vende cada diez minutos deja de venderse, OSA infiere estante vacío.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En OAA, ¿cómo se asegura que el stock de CAR refleje los movimientos de ERP?', 'Reescribiendo la tabla de artículos en cada orden de compra generada.', 'Cargando manualmente planillas Excel al inicio de cada turno comercial.', 'Conectando directamente los sensores de las estanterías por Bluetooth.', 'Mediante sincronización periódica de deltas de stock o eventos vía SLT.', 'D', 'Senior', 'La sincronización de deltas actualiza el ATP de CAR garantizando visibilidad en la tienda web.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Por qué la tabla /POSDW/TLOGF almacena los tickets en formato plano?', 'Para maximizar el throughput de inserción masiva sin costo de desnormalización.', 'Porque el motor de base de datos no soporta tablas con más de dos columnas.', 'Para evitar que los auditores externos puedan leer los montos de ventas.', 'Para comprimir los archivos de texto y enviarlos por fax a las sucursales.', 'A', 'Senior', 'La estructura plana agiliza la escritura masiva en memoria durante picos de venta.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En UDF, ¿cómo se tratan las ventas atípicas de una compra institucional única?', 'Se multiplican por diez para elevar artificialmente el pronóstico anual.', 'Se detectan como valores atípicos (Outliers) y se limpian de la serie base.', 'Se eliminan junto con los datos de todos los clientes de la tienda.', 'Se registran como faltantes de caja en la contabilidad general de FI.', 'B', 'Senior', 'La detección de outliers evita que compras esporádicas provoquen sobre-stock en compras.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Qué parámetro determina la duración de una reserva temporal en SAP OAA?', 'La velocidad de conexión a internet del dispositivo del cliente.', 'El saldo disponible en la tarjeta de crédito del comprador web.', 'El Time-to-Live (TTL) configurado en el perfil de sourcing omnicanal.', 'El número de visitas que recibe la página del producto al día.', 'C', 'Senior', 'El TTL libera automáticamente las reservas si el usuario no concreta la compra en el plazo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Cómo se conecta SAP CAR con herramientas analíticas como SAP Analytics Cloud?', 'Creando réplicas de datos en bases de datos de texto no estructuradas.', 'Exportando archivos de texto delimitados por comas a carpetas compartidas.', 'Imprimiendo los tableros y enviándolos físicamente por paquetería.', 'Mediante conexiones Live sobre vistas de cálculo en memoria de SAP HANA.', 'D', 'Senior', 'Las conexiones Live consultan directamente los datos de CAR sin replicación intermedia.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En POS DTA, ¿cómo se garantiza la segregación de funciones entre tiendas?', 'Asignando objetos de autorización por ID de tienda, canal y rol de usuario.', 'Instalando una base de datos SAP HANA física distinta en cada tienda.', 'Cambiando las contraseñas de red cada tres minutos en toda la empresa.', 'Desconectando las tiendas entre sí para que no compartan servidores.', 'A', 'Senior', 'Los objetos de autorización aseguran que el gerente de tienda solo visualice sus propios tickets.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Qué ventaja ofrece SAP CAR Replenishment Planning frente al MRP clásico de ERP?', 'Calcula compras asumiendo que la demanda de todos los productos es constante.', 'Utiliza pronósticos probabilísticos de UDF considerando capacidad de góndola.', 'Permite comprar sin autorización de presupuesto ni supervisión financiera.', 'Envía solicitudes de compra a los proveedores mediante llamadas telefónicas.', 'B', 'Senior', 'Integra distribución de probabilidades de demanda y restricciones de espacio de tienda.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', 'En OPP, ¿cómo se envían las reglas promocionales a tiendas con baja conectividad?', 'Pausando las promociones hasta que la tienda cuente con fibra óptica.', 'Dictando las fórmulas de descuento por teléfono al supervisor de cajas.', 'Exportando el repositorio de promociones hacia motores PPS locales en JSON.', 'Imprimiendo hojas de cálculo para que los cajeros apliquen descuentos a mano.', 'C', 'Senior', 'El motor PPS local consume las promociones offline manteniendo consistencia omnicanal.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) 
VALUES ('sap', '¿Qué mecanismo garantiza idempotencia en la recepción de tickets POS hacia CAR?', 'Registro exclusivo del apellido del cajero en turno sin marcas de tiempo.', 'Asignación de números aleatorios generados por la memoria de la impresora.', 'Uso de la dirección IP pública del enrutador de internet de la tienda.', 'Llave compuesta por Store ID, Workstation ID, Business Date y Sequence Number.', 'D', 'Senior', 'La combinación única de estos cuatro campos previene procesar el mismo ticket más de una vez.', 1);

